export function mekongPointInRing(lat, lon, ring) {
  let inside = false
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const yi = ring[i][0], xi = ring[i][1]
    const yj = ring[j][0], xj = ring[j][1]
    if ((yi > lat) !== (yj > lat) && lon < ((xj - xi) * (lat - yi)) / (yj - yi + 1e-12) + xi) {
      inside = !inside
    }
  }
  return inside
}

export function mekongFindProvince(lat, lon) {
  if (Array.isArray(lat)) { lon = lat[1]; lat = lat[0] }
  for (const p of MEKONG_PROVINCES_GEO) {
    for (const ring of p.rings) {
      if (mekongPointInRing(lat, lon, ring)) return p
    }
  }
  return null
}
